unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-D1","scope_ref":"P2","token":"D_1","meaning":"零配件1检测成本","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-D2","scope_ref":"P2","token":"D_2","meaning":"零配件2检测成本","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-A","scope_ref":"P2","token":"A","meaning":"装配成本","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-T","scope_ref":"P2","token":"T","meaning":"成品检测成本","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-S","scope_ref":"P2","token":"S","meaning":"拆解费用","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P","scope_ref":"P2","token":"P","meaning":"市场售价","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-L","scope_ref":"P2","token":"L","meaning":"调换损失","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E","scope_ref":"P2","token":"E","meaning":"单件成品期望利润","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P1U","scope_ref":"P4","token":"***","meaning":"零配件1次品率的置信上限","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P2U","scope_ref":"P4","token":"***","meaning":"零配件2次品率的置信上限","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PFU","scope_ref":"P4","token":"***","meaning":"成品次品率的置信上限","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E4","scope_ref":"P4","token":"E_4","meaning":"最坏情况下的期望利润","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEP","scope_ref":"P1","statement":"各零配件、半成品的次品事件在统计上相互独立（题目未明确说明，但此为所有概率计算的基础假设；如不成立则需联合分布，但题目未提供相关信息）。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"各零配件、半成品的次品事件在统计上相互独立（题目未明确说明，但此为所有概率计算的基础假设"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-PERFECT-DETECT","scope_ref":"P1","statement":"检测过程完美——检测合格品一定为正品，检测不合格品一定为次品，无漏检或误检（题目隐含“检测出的不合格零配件丢弃”）","source_type":"GIVEN","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"检测过程完美——检测合格品一定为正品，检测不合格品一定为次品，无漏检或误检（题目隐含“检测出的不合格零配件丢弃”）"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-FULL-REUSE","scope_ref":"P1","statement":"拆解得到的所有零配件均可重新进入装配流程，且拆解不损坏零配件（题目明确说明“拆解过程不会对零配件造成损坏”）","source_type":"GIVEN","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"拆解得到的所有零配件均可重新进入装配流程，且拆解不损坏零配件（题目明确说明“拆解过程不会对零配件造成损坏”）"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INFINITE-HORIZON","scope_ref":"P1","statement":"决策分析基于单件成品的期望利润，假定各件成品的生产过程独立且参数稳定（稳态长期平均）","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"决策分析基于单件成品的期望利润，假定各件成品的生产过程独立且参数稳定（稳态长期平均）"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BINOMIAL","scope_ref":"P1","statement":"抽样为简单随机抽样，批中次品数服从二项分布（批量大，抽取比例小，可近似为有放回）。","source_type":"APPROXIMATION","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"抽样为简单随机抽样，批中次品数服从二项分布（批量大，抽取比例小，可近似为有放回）"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BATCH-HOMOG","scope_ref":"P1","statement":"批内产品次品率恒定且均匀，不存在层间差异。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"批内产品次品率恒定且均匀，不存在层间差异"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-RECURSION-END","scope_ref":"P2","statement":"拆解-重装配循环中，每次独立且参数不变；该递归过程的期望利润收敛（因次品率 < 1），可用等比级数公式求和。","source_type":"DERIVED","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"拆解-重装配循环中，每次独立且参数不变"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NO-SEMI-DISMANTLE","scope_ref":"P3","statement":"半成品检测不合格后直接丢弃，不可拆解为零部件（题目仅允许对成品拆解）。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"半成品检测不合格后直接丢弃，不可拆解为零部件（题目仅允许对成品拆解）"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEP-NET","scope_ref":"P3","statement":"装配网络中各级次品事件独立。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"装配网络中各级次品事件独立"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-CI-METHOD","scope_ref":"P4","statement":"采用 Clopper-Pearson 精确置信区间（二项分布）计算次品率置信上限，置信水平与问题1信度匹配（例如 95%）。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"采用 Clopper-Pearson 精确置信区间（二项分布）计算次品率置信上限，置信水平与问题1信度匹配（例如 95%）"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-WORST-CASE","scope_ref":"P4","statement":"决策者遵循最坏情况鲁棒准则：在所有可能真实次品率（位于置信区间内）中，选取使期望利润最低的组合，然后选择在此最坏情况下利润最高的策略。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"决策者遵循最坏情况鲁棒准则：在所有可能真实次品率（位于置信区间内）中，选取使期望利润最低的组合，然后选择在此最坏情况下利润最高的策略"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAMPLING-RESULT","scope_ref":"P4","statement":"假设对每种零配件/半成品的抽样检测结果为其标称次品率附近的某个合理观测值，例如抽样 n 件观察到的不合格数恰好使点估计等于原标称值（概率最高点），以确保结果可比性。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"假设对每种零配件/半成品的抽样检测结果为其标称次品率附近的某个合理观测值，例如抽样 n 件观察到的不合格数恰好使点估计等于原标称值（概率最高点），以确保结果可比性"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-BINOM","scope_ref":"P1","expression":"P(X <= c | p=0.1) = sum_{k=0}^{c} binom(n,k) (0.1)^k (0.9)^{n-k}","representation":"LATEX_PRESENTATION","lhs_symbols":[],"rhs_symbols":["S-N","S-C","S-P0"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"二项分布累积概率","e1_span":"计算二项累积概率 $\sum_{k=0}^{c} \binom{n}{k} (0.1)^k (0.9)^{n-k}$ 和补概率"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-REJECT","scope_ref":"P1","expression":"P(X > c | p=0.1) <= 0.05","representation":"LATEX_PRESENTATION","lhs_symbols":[],"rhs_symbols":["S-N","S-C","S-P0","S-ALPHA"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOM"],"source":"95%信度拒收条件","e1_span":"P(X > c \mid p=0.1) \le 0.05 （对应 95% 信度拒收）"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-ACCEPT","scope_ref":"P1","expression":"P(X <= c | p=0.1) >= 0.90","representation":"LATEX_PRESENTATION","lhs_symbols":[],"rhs_symbols":["S-N","S-C","S-P0","S-BETA"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOM"],"source":"90%信度接收条件","e1_span":"P(X \le c \mid p=0.1) \ge 0.90 （对应 90% 信度接收）"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PROFIT","scope_ref":"P2","expression":"E = 收入 - 成本","representation":"LATEX_PRESENTATION","lhs_symbols":["S-E"],"rhs_symbols":["S-P","S-C1","S-C2","S-D1","S-D2","S-A","S-T","S-S","S-L"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":[],"source":"期望利润公式","e1_span":"利润 = 收入 - 成本"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-CI","scope_ref":"P4","expression":"p_upper = Clopper-Pearson 置信上限","representation":"LATEX_PRESENTATION","lhs_symbols":["S-P1U","S-P2U","S-PFU"],"rhs_symbols":["S-N","S-C"],"equation_type":"DERIVED","unit":"dimensionless","depends_on":[],"source":"Clopper-Pearson精确置信区间","e1_span":"采用 Clopper-Pearson 精确置信区间（二项分布）计算次品率置信上限"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-INDEP","A-PERFECT-DETECT","A-FULL-REUSE","A-INFINITE-HORIZON","A-BINOMIAL","A-BATCH-HOMOG"],"variable_refs":["S-N","S-C"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1},{"symbol_ref":"S-ALPHA","value":0.05},{"symbol_ref":"S-BETA","value":0.10}],"equation_refs":["EQ-BINOM","EQ-REJECT","EQ-ACCEPT"],"constraints":["P(X > c | p=0.1) <= 0.05","P(X <= c | p=0.1) >= 0.90"],"objective":"最小化样本量 n","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-INDEP","A-PERFECT-DETECT","A-FULL-REUSE","A-INFINITE-HORIZON","A-RECURSION-END"],"variable_refs":["S-E"],"parameter_refs":[{"symbol_ref":"S-P1","value":0.1},{"symbol_ref":"S-P2","value":0.1},{"symbol_ref":"S-PF","value":0.1},{"symbol_ref":"S-C1","value":2},{"symbol_ref":"S-C2","value":8},{"symbol_ref":"S-D1","value":1},{"symbol_ref":"S-D2","value":1},{"symbol_ref":"S-A","value":8},{"symbol_ref":"S-T","value":3},{"symbol_ref":"S-S","value":5},{"symbol_ref":"S-P","value":56},{"symbol_ref":"S-L","value":6}],"equation_refs":["EQ-PROFIT"],"constraints":[],"objective":"最大化单件成品的期望利润 E","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-INDEP","A-PERFECT-DETECT","A-FULL-REUSE","A-INFINITE-HORIZON","A-RECURSION-END","A-NO-SEMI-DISMANTLE","A-INDEP-NET"],"variable_refs":[],"parameter_refs":[],"equation_refs":[],"constraints":[],"objective":"最大化期望利润（枚举8192种策略）","dependencies":["M2"]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-INDEP","A-PERFECT-DETECT","A-FULL-REUSE","A-INFINITE-HORIZON","A-RECURSION-END","A-CI-METHOD","A-WORST-CASE","A-SAMPLING-RESULT"],"variable_refs":["S-P1U","S-P2U","S-PFU","S-E4"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1}],"equation_refs":["EQ-CI","EQ-PROFIT"],"constraints":[],"objective":"最坏情况下最大化期望利润（min-max）","dependencies":["M1","M2"]}}],"code":"const fs = require('fs');
function binomCDF(n, c, p) {
  let s = 0;
  let term = Math.pow(1-p, n);
  for (let k = 0; k <= c; k++) {
    s += term;
    term *= (n-k)/(k+1) * p/(1-p);
  }
  return s;
}
function findMinN(p0, alpha, beta) {
  for (let n = 1; n <= 200; n++) {
    for (let c = 0; c <= n; c++) {
      const acc = binomCDF(n, c, p0);
      const rej = 1 - acc;
      if (rej <= alpha && acc >= 1 - beta) {
        return { n, c };
      }
    }
  }
  return { n: -1, c: -1 };
}
function clopperPearsonUpper(n, k, conf) {
  if (k >= n) return 1;
  const alpha = 1 - conf;
  let lo = 0, hi = 1;
  for (let i = 0; i < 100; i++) {
    const mid = (lo + hi) / 2;
    let s = 0;
    let term = Math.pow(1-mid, n);
    for (let j = 0; j <= k; j++) {
      s += term;
      term *= (n-j)/(j+1) * mid/(1-mid);
    }
    if (s > alpha) hi = mid; else lo = mid;
  }
  return (lo + hi) / 2;
}
function expectedProfit(p1, p2, pf, C1, C2, D1, D2, A, T, S, P, L, d1, d2, dF, dD) {
  const q1 = d1 ? 0 : p1;
  const q2 = d2 ? 0 : p2;
  const cost1 = C1 + (d1 ? D1 : 0);
  const cost2 = C2 + (d2 ? D2 : 0);
  const goodPair = (1-q1)*(1-q2);
  const goodFinal = goodPair * (1-pf);
  const badFinal = 1 - goodFinal;
  const baseCost = cost1 + cost2 + A + (dF ? T : 0);
  let E;
  if (dF) {
    if (dD) {
      const salvage = (1-q1)*(1-q2)*(1-pf) * P - (dD ? S : 0);
      E = goodFinal * P - baseCost - badFinal * S + badFinal * (goodFinal * P - baseCost - badFinal * S) / (1 - badFinal);
    } else {
      E = goodFinal * P - baseCost;
    }
  } else {
    E = goodFinal * P - baseCost - badFinal * L;
  }
  return E;
}
const q1 = findMinN(0.1, 0.05, 0.10);
const n = q1.n, c = q1.c;
const k1 = Math.round(n * 0.1);
const k2 = Math.round(n * 0.1);
const kf = Math.round(n * 0.1);
const p1u = clopperPearsonUpper(n, k1, 0.95);
const p2u = clopperPearsonUpper(n, k2, 0.95);
const pfu = clopperPearsonUpper(n, kf, 0.95);
const strategies = [];
for (let d1 = 0; d1 <= 1; d1++) for (let d2 = 0; d2 <= 1; d2++) for (let dF = 0; dF <= 1; dF++) for (let dD = 0; dD <= 1; dD++) {
  const E = expectedProfit(0.1, 0.1, 0.1, 2, 8, 1, 1, 8, 3, 5, 56, 6, d1, d2, dF, dD);
  strategies.push({ d1, d2, dF, dD, E });
}
strategies.sort((a,b) => b.E - a.E);
const best2 = strategies[0];
const E4 = expectedProfit(p1u, p2u, pfu, 2, 8, 1, 1, 8, 3, 5, 56, 6, best2.d1, best2.d2, best2.dF, best2.dD);
const out = {
  n_fixed: n,
  c_fixed: c,
  p1_upper: p1u,
  p2_upper: p2u,
  pf_upper: pfu,
  best2_E: best2.E,
  best2_d1: best2.d1,
  best2_d2: best2.d2,
  best2_dF: best2.dF,
  best2_dD: best2.dD,
  best4_E: E4,
  best4_d1: best2.d1,
  best4_d2: best2.d2,
  best4_dF: best2.dF,
  best4_dD: best2.dD
};
fs.writeFileSync('results.json', JSON.stringify(out, null, 2));
fs.writeFileSync('numeric_config.json', JSON.stringify({
  discretization: {},
  physical: { "S-P0": 0.1, "S-ALPHA": 0.05, "S-BETA": 0.10, "S-P1": 0.1, "S-P2": 0.1, "S-PF": 0.1, "S-C1": 2, "S-C2": 8, "S-D1": 1, "S-D2": 1, "S-A": 8, "S-T": 3, "S-S": 5, "S-P": 56, "S-L": 6 },
  choices: { "method_q1": "binomial_exact_enumeration", "method_q2": "decision_tree_enumeration", "method_q4": "worst_case_robust" },
