function binomPmf(n,k,p){ if(k<0||k>n) return 0; let logP = 0; for(let i=1;i<=k;i++) logP += Math.log(n-k+i)-Math.log(i); logP += k*Math.log(p)+(n-k)*Math.log(1-p); return Math.exp(logP); }
function binomCdf(n,c,p){ let s=0; for(let k=0;k<=c;k++) s+=binomPmf(n,k,p); return s; }
function findN(p0,alpha,beta){ for(let n=1;n<=500;n++){ for(let c=0;c<=n;c++){ const accept=binomCdf(n,c,p0); const reject=1-accept; if(reject<=alpha && accept>=beta) return {n,c,accept,reject}; } } return null; }
const q1 = findN(0.1,0.05,0.90);
function clopperPearsonUpper(k,n,conf){ if(k>=n) return 1; const alpha=1-conf; let lo=0, hi=1; for(let iter=0;iter<200;iter++){ const mid=(lo+hi)/2; let s=0; for(let i=0;i<=k;i++) s+=binomPmf(n,i,mid); if(s>alpha) hi=mid; else lo=mid; } return hi; }
const n4=60, c4=2;
const k1=Math.round(0.1*n4), k2=Math.round(0.1*n4), kf=Math.round(0.1*n4);
