function binomCdf(n, p, c) {
  let s = 0, term = Math.pow(1-p, n);
  for (let k = 0; k <= c; k++) {
    s += term;
    term *= (n-k)/(k+1) * p/(1-p);
  }
  return s;
}
function findMinN(p0, alpha, beta) {
  for (let n = 1; n <= 500; n++) {
    for (let c = 0; c <= n; c++) {
      const accept = binomCdf(n, p0, c);
      const reject = 1 - accept;
      if (reject <= alpha && accept >= 1 - beta) return {n, c, accept, reject};
    }
  }
  return null;
}
const q1 = findMinN(0.1, 0.05, 0.10);
function clopperPearsonUpper(n, k, conf) {
  if (k >= n) return 1;
  const alpha = 1 - conf;
  let lo = 0, hi = 1;
  for (let i = 0; i < 100; i++) {
    const mid = (lo + hi) / 2;
    let cdf = 0, term = Math.pow(1-mid, n);
    for (let j = 0; j <= k; j++) {
      cdf += term;
      term *= (n-j)/(j+1) * mid/(1-mid);
    }
    if (cdf > alpha) hi = mid; else lo = mid;
  }
  return (lo + hi) / 2;
}
function profitQ2(d1, d2, dt, ds, p1, p2, pf, C1, C2, D1, D2, A, T, S, P, L) {
  const q1 = d1 ? 1 : 1 - p1;
  const q2 = d2 ? 1 : 1 - p2;
  const cost1 = C1 + (d1 ? D1 : 0);
  const cost2 = C2 + (d2 ? D2 : 0);
  const good = q1 * q2 * (1 - pf);
  const bad = 1 - good;
  const baseCost = cost1 + cost2 + A + (dt ? T : 0);
  let revenue = 0, extraCost = 0;
  if (dt) {
    revenue = good * P;
    if (ds) {
      extraCost = bad * S;
      const rec = profitQ2(d1, d2, dt, ds, p1, p2, pf, C1, C2, D1, D2, A, T, S, P, L);
      extraCost += bad * (baseCost - rec);
    } else {
      extraCost = bad * L;
    }
  } else {
    revenue = good * P;
    extraCost = bad * L;
  }
  return revenue - baseCost - extraCost;
}
function bestQ2(p1, p2, pf, C1, C2, D1, D2, A, T, S, P, L) {
  let best = -Infinity, bestStrat = null;
  for (let d1 = 0; d1 <= 1; d1++) for (let d2 = 0; d2 <= 1; d2++) for (let dt = 0; dt <= 1; dt++) for (let ds = 0; ds <= 1; ds++) {
    const val = profitQ2(d1, d2, dt, ds, p1, p2, pf, C1, C2, D1, D2, A, T, S, P, L);
