function binomPmf(k, n, p) {
  if (k < 0 || k > n) return 0;
  let logP = 0;
  for (let i = 1; i <= k; i++) logP += Math.log(n - k + i) - Math.log(i);
  logP += k * Math.log(p) + (n - k) * Math.log(1 - p);
  return Math.exp(logP);
}
function binomCdf(c, n, p) {
  let s = 0;
  for (let k = 0; k <= c; k++) s += binomPmf(k, n, p);
  return s;
}
function findMinN(p0, alpha, beta) {
  for (let n = 1; n <= 500; n++) {
    for (let c = 0; c <= n; c++) {
      const cdf = binomCdf(c, n, p0);
      const reject = 1 - cdf;
      if (reject <= alpha && cdf >= 1 - beta) return { n, c };
    }
  }
  return { n: 0, c: 0 };
}
function clopperPearsonUpper(k, n, level) {
  if (k >= n) return 1;
  const alpha = 1 - level;
  let lo = 0, hi = 1;
  for (let i = 0; i < 100; i++) {
    const mid = (lo + hi) / 2;
    const cdf = binomCdf(k, n, mid);
    if (cdf > alpha) hi = mid; else lo = mid;
  }
  return hi;
}
function expectedProfit(params) {
  const { p1, p2, pf, C1, C2, D1, D2, A, T, S, P, L, d1, d2, df, dm } = params;
  const q1 = d1 ? 0 : p1;
  const q2 = d2 ? 0 : p2;
  const good1 = 1 - q1;
  const good2 = 1 - q2;
  const goodAssembled = good1 * good2 * (1 - pf);
  const costParts = C1 + C2 + (d1 ? D1 : 0) + (d2 ? D2 : 0);
  const costAssemble = A;
  const costTest = df ? T : 0;
  const costDismantle = dm ? S : 0;
  const revenue = P;
  const loss = L;
  const goodToMarket = df ? goodAssembled : 1;
  const badToMarket = df ? 0 : (1 - goodAssembled);
  const profit = revenue * goodToMarket - loss * badToMarket - costParts - costAssemble - costTest - costDismantle;
  return profit;
}
function enumerateQ2(params) {
  let best = { profit: -Infinity, strategy: null };
  for (let d1 = 0; d1 <= 1; d1++) for (let d2 = 0; d2 <= 1; d2++) for (let df = 0; df <= 1; df++) for (let dm = 0; dm <= 1; dm++) {
